using System.Security.Claims;using Asp.Versioning;using FluentValidation;using LostFound.Application.Contracts;using LostFound.Domain.Entities;using LostFound.Infrastructure.Persistence;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace LostFound.Api.Controllers;
[Authorize,ApiController,ApiVersion(1),Route("api/v{version:apiVersion}/items/{itemId:guid}/verification-questions")]
public sealed class VerificationQuestionsController(LostFoundDbContext db,IValidator<SetVerificationQuestionsRequest> validator):ControllerBase{private Guid UserId=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);[HttpGet]public async Task<ActionResult> Get(Guid itemId,CancellationToken ct){if(!await db.Items.AnyAsync(x=>x.Id==itemId,ct))return NotFound();return Ok(await db.ClaimQuestions.Where(x=>x.ItemId==itemId&&x.IsActive).OrderBy(x=>x.SortOrder).Select(x=>new VerificationQuestionResponse(x.Id,x.Prompt,x.SortOrder)).ToListAsync(ct));}[HttpPut]public async Task<ActionResult> Set(Guid itemId,SetVerificationQuestionsRequest r,CancellationToken ct){var vr=await validator.ValidateAsync(r,ct);if(!vr.IsValid)return BadRequest(new ValidationProblemDetails(vr.ToDictionary()));var item=await db.Items.SingleOrDefaultAsync(x=>x.Id==itemId,ct);if(item is null)return NotFound();if(item.OwnerId!=UserId)return Forbid();if(await db.Claims.AnyAsync(x=>x.ItemId==itemId&&x.Status!=ClaimStatus.Cancelled&&x.Status!=ClaimStatus.Rejected,ct))return Conflict(new ProblemDetails{Title="Questions are locked after a claim starts",Status=409});await db.ClaimQuestions.Where(x=>x.ItemId==itemId).ExecuteDeleteAsync(ct);db.ClaimQuestions.AddRange(r.Questions.Select((q,i)=>new ClaimQuestion{ItemId=itemId,Prompt=q.Trim(),SortOrder=i}));await db.SaveChangesAsync(ct);return Ok(await db.ClaimQuestions.Where(x=>x.ItemId==itemId).OrderBy(x=>x.SortOrder).Select(x=>new VerificationQuestionResponse(x.Id,x.Prompt,x.SortOrder)).ToListAsync(ct));}}
